export type ReviewStatus='risk_found'|'no_issue_found'|'insufficient_evidence'|'not_applicable';
export type LegacyExecutionState='not_run'|'partially_reviewed'|'reviewed';
export interface EvidenceRef { unit_id:string; start:number; end:number; quote?:string; file_id?:string; file_sha256?:string; page?:number|null; }
export interface SourceUnit { id:string; file_id:string; order:number; raw_text:string; normalized_text:string; normal_to_raw:number[]; page:number|null; part?:string; table_id?:string; row?:number; cell?:number; clause_label:string|null; }
export interface OriginalComment {comment_id:string;audit_id:string;author:string|null;date:string|null;date_role?:'comment_metadata_not_contract_signature';text:string;selected_text:string;anchor_state:'anchored'|'anomalous';spans:EvidenceRef[];anomalies:string[];}
export interface ReviewCheck {id:string;check_id:string;title:string;execution_state:LegacyExecutionState;executionState:ExecutionState;reviewOutcome:ReviewOutcome|null;status:ReviewStatus|null;model_status?:ReviewStatus;inspected_unit_ids?:string[];uninspected_unit_ids?:string[];evidence_refs:EvidenceRef[];explanation:string;unresolved_questions:string[];}
export interface ReviewContext {contract_type:'equipment_purchase_cn'|string;stance:'buyer'|'seller'|'neutral';region:string;stage:'pre_signing'|'performance'|'dispute';signing_date?:string;signing_date_verified?:boolean;guidance?:string;}
export interface ReviewFinding {finding_id:string;check_ids:string[];category:'文字错误'|'材料缺失'|'商务风险'|'法律风险'|'条款冲突'|'待确认';priority:'高'|'需关注'|'低';priority_reason:string;origin:'program'|'model'|'original_comment'|'external';level:'deterministic_fact'|'candidate_risk'|'model_judgment';evidence_refs:EvidenceRef[];explanation:string;interpretation_space:string;suggestion:string;business_parameters:string[];legal_sources:unknown[];legal_verification:'unverified';unresolved_questions:string[];}
export interface ExternalTestApproval {approval_id:string;provider:string;base_url:string;model:string;material_classification:'synthetic'|'public';input_sha256:string[];context_sha256:string;policy_sha256:string|null;}
export type ExecutionState = 'pending'|'running'|'accepted'|'protocol_failed'|'timed_out'|'budget_exhausted'|'cancelled'|'blocked';
export type ReviewOutcome = 'risk_candidate'|'no_issue_observed_in_scope'|'insufficient_material'|'not_applicable';
export interface TopicReceipt {check_id:string;executionState:ExecutionState;reviewOutcome:ReviewOutcome|null;findingRefs:string[];evidence_refs:unknown[];pendingFields:unknown[];attemptRefs:string[];}
export interface ReportIssueGroup {groupId:string;title:string;memberFindingIds:string[];topicIds:string[];subIssues:Array<{findingIds:string[];kind:'duplicate_expression'|'related_issue'|'conflicting_view';summary:string;status:string}>;evidenceLinks:Array<{evidenceId:string;role:'support'|'counter'|'condition'|'scope_limit'|'reported_context'}>;unresolvedQuestions:string[];groupingMethod:string;groupingReason:string;}
